  return new Promise((resolve) => {
    const done = () => resolve({ok:true, duration:v.duration, time:v.currentTime, w:v.videoWidth, h:v.videoHeight, paused:v.paused});
    v.currentTime = 1.2;
    v.addEventListener('seeked', done, {once:true});
    setTimeout(done, 1200);
  });
}

